using System.Text;
using System.Text.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Microsoft.EntityFrameworkCore;
namespace BuildingFlow.Infrastructure;
public sealed class ListingStore(BuildingFlowDbContext db,IFileStorage storage,IListingAuthorityVerifier verifier,TimeProvider clock,SessionContextStore contexts):IListingStore{
 private IQueryable<WebsiteSite> Sites(Guid p,AccessScope a)=>db.Set<WebsiteSite>().Where(s=>s.PropertyId==p&&s.IsEnabled&&(!contexts.Enabled||contexts.ManagementProperties("MANAGER").Any(x=>x.PropertyId==p))&&db.Properties.Any(x=>x.Id==p&&x.IsEnabled&&!x.IsDeleted&&(a.ReadAll||db.PropertyMemberships.Any(m=>m.PropertyId==p&&m.UserId==a.UserId&&m.IsEnabled&&!m.IsDeleted))));
 private async Task<WebsiteSite?> Lock(Guid p,AccessScope a,CancellationToken t){if(!await Sites(p,a).AnyAsync(t))return null;await db.Database.ExecuteSqlInterpolatedAsync($"SELECT 1 FROM properties WHERE id={p} FOR UPDATE",t);return await Sites(p,a).SingleOrDefaultAsync(t);}
 private void Touch(BaseEntity e)=>db.Entry(e).Property(x=>x.IsEnabled).IsModified=true;
 private static void Version(long v,long actual){if(v!=actual)throw new HierarchyConflictException(ErrorCatalog.RecordChanged.Create());}
 private static void State()=>throw new HierarchyConflictException(ErrorCatalog.ListingState.Create());
 private IQueryable<PropertyListing> Rows(Guid p,Guid site)=>db.Set<PropertyListing>().Where(x=>x.PropertyId==p&&x.SiteId==site);
 private async Task<ListingDto> Dto(PropertyListing l,CancellationToken t,bool replay=false)=>new(l.Id,l.UnitId,l.Kind,l.Title,l.Description,l.Price,l.RoomLayout,l.GrossArea,l.NetArea,l.FloorLabel,l.BuildingLabel,JsonSerializer.Deserialize<string[]>(l.Features)!,l.Status,l.PublishUntil,l.ConsentKind,l.AgentLicenseNo,l.ComplianceNote,l.Version,await db.Set<ListingPhoto>().Where(x=>x.PropertyId==l.PropertyId&&x.ListingId==l.Id).OrderBy(x=>x.SortOrder).Select(x=>x.MediaId).ToArrayAsync(t),replay);
 private void Event(PropertyListing l,string action,string? note=null)=>db.Add(new ListingEvent(l.PropertyId,l.Id,action,note,l.Version+1));
 public async Task<IReadOnlyList<ListingUnitOption>?> Units(Guid p,AccessScope a,CancellationToken t){if(!await Sites(p,a).AnyAsync(t))return null;return await db.Units.Where(u=>u.PropertyId==p&&u.IsEnabled&&(u.BuildingId==null||db.Buildings.Any(b=>b.Id==u.BuildingId&&b.PropertyId==p&&b.IsEnabled))).OrderBy(u=>u.Number).Take(500).Select(u=>new ListingUnitOption(u.Id,u.Number)).ToArrayAsync(t);}
 public async Task<ListingDto?> Get(Guid p,Guid id,AccessScope a,CancellationToken t){var l=await db.Set<PropertyListing>().SingleOrDefaultAsync(x=>x.Id==id&&x.PropertyId==p&&Sites(p,a).Any(s=>s.Id==x.SiteId),t);return l is null?null:await Dto(l,t);}
 public async Task<IReadOnlyList<ListingDto>?> List(Guid p,AccessScope a,CancellationToken t){var site=await Sites(p,a).SingleOrDefaultAsync(t);if(site is null)return null;var rows=await Rows(p,site.Id).OrderByDescending(x=>x.CreatedAt).Take(500).ToArrayAsync(t);var result=new List<ListingDto>();foreach(var l in rows)result.Add(await Dto(l,t));return result;}
 public async Task<ListingDto?> Save(Guid p,Guid? id,ListingEdit r,AccessScope a,CancellationToken t){await using var tx=await db.Database.BeginTransactionAsync(t);var site=await Lock(p,a,t);if(site is null)return null;
  if(r.UnitId is not null&&!await db.Units.AnyAsync(u=>u.Id==r.UnitId&&u.PropertyId==p&&u.IsEnabled&&(u.BuildingId==null||db.Buildings.Any(b=>b.Id==u.BuildingId&&b.PropertyId==p&&b.IsEnabled)),t))ListingValidation.Invalid();
  var fingerprint=WebsiteImage.Sha(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(r with{Version=0})));
  PropertyListing? l;
  if(id is null){l=await db.Set<PropertyListing>().IgnoreQueryFilters().SingleOrDefaultAsync(x=>x.PropertyId==p&&x.SiteId==site.Id&&x.RequestId==r.RequestId,t);if(l is not null){if(l.IsDeleted||l.Fingerprint!=fingerprint)throw new HierarchyConflictException(ErrorCatalog.WebsiteRequestConflict.Create());return await Dto(l,t,true);}if(await Rows(p,site.Id).CountAsync(t)>=500)State();l=new(p,site.Id,r.RequestId,fingerprint);db.Add(l);}else{l=await Rows(p,site.Id).SingleOrDefaultAsync(x=>x.Id==id,t);if(l is null)return null;Version(r.Version,l.Version);if(l.Status is "WITHDRAWN" or "EXPIRED")l.Invalidate();}
  var old=l.Status;l.Edit(r.UnitId,r.Kind,r.Title,r.Description,r.Price,r.RoomLayout,r.GrossArea,r.NetArea,r.FloorLabel,r.BuildingLabel,JsonSerializer.Serialize(r.Features));Event(l,id is null?"CREATE":old is "APPROVED" or "PUBLISHED"?"EDIT_AFTER_APPROVAL":"EDIT");if(id is not null)Touch(l);Touch(site);await db.SaveChangesAsync(t);await tx.CommitAsync(t);return await Dto(l,t);
 }
 public async Task<ListingDto?> Photos(Guid p,Guid id,ListingPhotos r,AccessScope a,CancellationToken t){await using var tx=await db.Database.BeginTransactionAsync(t);var site=await Lock(p,a,t);if(site is null)return null;var l=await Rows(p,site.Id).SingleOrDefaultAsync(x=>x.Id==id,t);if(l is null)return null;Version(r.Version,l.Version);if(await db.Set<WebsiteMedia>().CountAsync(m=>m.PropertyId==p&&m.SiteId==site.Id&&m.IsEnabled&&r.MediaIds.Contains(m.Id),t)!=r.MediaIds.Length)ListingValidation.Invalid();var old=await db.Set<ListingPhoto>().Where(x=>x.PropertyId==p&&x.ListingId==id).ToArrayAsync(t);db.RemoveRange(old);await db.SaveChangesAsync(t);for(int i=0;i<r.MediaIds.Length;i++)db.Add(new ListingPhoto(p,site.Id,id,r.MediaIds[i],i));l.Invalidate(l.Status is "APPROVED" or "PUBLISHED" or "PENDING_APPROVAL");Event(l,"PHOTOS");Touch(l);Touch(site);await db.SaveChangesAsync(t);await tx.CommitAsync(t);return await Dto(l,t);}
 public async Task<ListingDto?> Consent(Guid p,Guid id,ListingConsent r,AccessScope a,CancellationToken t){await using var tx=await db.Database.BeginTransactionAsync(t);var site=await Lock(p,a,t);if(site is null)return null;var l=await Rows(p,site.Id).SingleOrDefaultAsync(x=>x.Id==id,t);if(l is null)return null;Version(r.Version,l.Version);var key=$"websites/{site.Id:N}/listing-consents/{Guid.NewGuid():N}";l.Consent(r.Kind,key,WebsiteImage.Sha(r.Bytes),r.ContentType,r.Bytes.Length,r.AgentLicenseNo);await storage.UploadAsync(key,new MemoryStream(r.Bytes,false),r.ContentType,t);Event(l,"CONSENT");Touch(l);Touch(site);await db.SaveChangesAsync(t);await tx.CommitAsync(t);return await Dto(l,t);}
 public async Task<WebsiteMediaContent?> ConsentContent(Guid p,Guid id,AccessScope a,CancellationToken t){var l=await db.Set<PropertyListing>().SingleOrDefaultAsync(x=>x.Id==id&&x.PropertyId==p&&Sites(p,a).Any(s=>s.Id==x.SiteId),t);if(l?.ConsentObjectKey is null)return null;await using var s=await storage.DownloadAsync(l.ConsentObjectKey,t);using var m=new MemoryStream();var buffer=new byte[8192];int n;while((n=await s.ReadAsync(buffer,t))>0){if(m.Length+n>10*1024*1024)throw new InvalidOperationException("Invalid private document.");m.Write(buffer,0,n);}var bytes=m.ToArray();if(bytes.Length!=l.ConsentSize||WebsiteImage.Sha(bytes)!=l.ConsentSha256)throw new InvalidOperationException("Invalid private document.");return new(bytes,l.ConsentContentType!,l.ConsentSha256!);}
 public async Task<ListingDto?> Act(Guid p,Guid id,string action,ListingAction r,AccessScope a,CancellationToken t){if(contexts.Enabled&&action!="SUBMIT"&&!await contexts.PropertyAllowedAsync(p,"SITE_ADMIN",t))return null;await using var tx=await db.Database.BeginTransactionAsync(t);var site=await Lock(p,a,t);if(site is null)return null;var l=await Rows(p,site.Id).SingleOrDefaultAsync(x=>x.Id==id,t);if(l is null)return null;Version(r.Version,l.Version);
  if(action is "SUBMIT" or "PUBLISH"){if(l.ConsentObjectKey is null)throw new HierarchyConflictException(ErrorCatalog.ListingConsent.Create());if(!await db.Set<ListingPhoto>().AnyAsync(x=>x.PropertyId==p&&x.ListingId==id,t))State();}
  ListingAuthorityVerification? verification=null;if(action=="PUBLISH"){if(l.Status!="APPROVED")State();verification=await verifier.Verify(p,id,t);if(verification is null||r.PublishUntil is null||verification.ValidUntil<r.PublishUntil)throw new HierarchyConflictException(ErrorCatalog.ListingVerification.Create());}
  try{l.Transition(action,r.Reason,clock.GetUtcNow(),r.PublishUntil,verification?.Reference);}catch(ArgumentException){State();}Event(l,action,r.Reason);Touch(l);Touch(site);await db.SaveChangesAsync(t);await tx.CommitAsync(t);return await Dto(l,t);
 }
 public async Task<bool> Delete(Guid p,Guid id,long v,AccessScope a,CancellationToken t){await using var tx=await db.Database.BeginTransactionAsync(t);var site=await Lock(p,a,t);if(site is null)return false;var l=await Rows(p,site.Id).SingleOrDefaultAsync(x=>x.Id==id,t);if(l is null)return false;Version(v,l.Version);if(l.Status!="DRAFT")State();db.Remove(l);Event(l,"DELETE");Touch(site);await db.SaveChangesAsync(t);await tx.CommitAsync(t);return true;}
 public async Task<IReadOnlyList<ListingEventDto>?> Events(Guid p,Guid id,AccessScope a,CancellationToken t){if(!await db.Set<PropertyListing>().AnyAsync(x=>x.PropertyId==p&&x.Id==id&&Sites(p,a).Any(s=>s.Id==x.SiteId),t))return null;return await db.Set<ListingEvent>().Where(x=>x.PropertyId==p&&x.ListingId==id).OrderBy(x=>x.CreatedAt).Select(x=>new ListingEventDto(x.Id,x.Action,x.Note,x.ListingVersion,x.CreatedAt,x.CreatedBy)).ToArrayAsync(t);}
}
